# Add a four-column variation without changing the three-item process diagram.
needle='.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:2.4mm;margin:2.5mm 0 4mm}'
if s.count(needle)!=1: raise SystemExit('steps css anchor missing')
s=s.replace(needle,needle+'\n.steps.four{grid-template-columns:repeat(4,1fr)}',1)
p.write_text(s)
print('Applied',len(repls),'content replacements plus four-step CSS.')
